27	    /// 自 v2.0.x 起 `inventoryManager.projects` 不再持有 finishedImage Data，
28	    /// 改用 `projectIDsWithFinishedImage` 集合做 SQL 层存在性查询的结果缓存。
29	    private var projectsByDate: [Date: [ProjectRecord]] {
30	        let hasImageIDs = inventoryManager.projectIDsWithFinishedImage
31	        let projects = inventoryManager.projects.filter {
32	            hasImageIDs.contains($0.id) && $0.completedDate != nil
33	        }
34	        var grouped: [Date: [ProjectRecord]] = [:]
35	        for project in projects {
36	            if let completedDate = project.completedDate {
37	                let dayStart = calendar.startOfDay(for: completedDate)
